begin;

create function pg_temp.assert_true(value boolean,label text) returns void language plpgsql as $$begin if value is not true then raise exception 'FAILED: %',label;end if;end$$;
create function pg_temp.reject(query text,code text default null) returns void language plpgsql as $$declare blocked boolean:=false;begin begin execute query;exception when others then if code is not null and SQLSTATE<>code then raise;end if;blocked:=true;end;if not blocked then raise exception 'Unauthorized/invalid operation succeeded: %',query;end if;end$$;
set local role authenticated;
set local request.jwt.claim.sub='10000000-0000-0000-0000-000000000001';
select set_config('p2.session',public.create_class_session('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000002',now()-interval '2 hours',now()-interval '1 hour','Atomic checkout')::text,true);
select pg_temp.reject($q$select public.create_class_session('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000003',now(),now()+interval '1 hour','Wrong teacher')$q$);
set local request.jwt.claim.sub='10000000-0000-0000-0000-000000000003';
select pg_temp.assert_true((select count(*)=0 from public.class_sessions),'Teacher B cannot read A');
select pg_temp.reject('select public.start_class_session('''||current_setting('p2.session')||''')','42501');
set local request.jwt.claim.sub='10000000-0000-0000-0000-000000000002';
select public.start_class_session(current_setting('p2.session')::uuid);
select pg_temp.assert_true((select count(*)=5 from public.session_student_records),'Roster snapshot');
select pg_temp.reject('insert into public.session_student_records(session_id,student_id) values('''||current_setting('p2.session')||''',''30000000-0000-0000-0000-000000000006'')','42501');
select set_config('p2.data',(select jsonb_build_object('lesson_content','Lesson','homework_assigned','Practice','records',jsonb_agg(jsonb_build_object('student_id',student_id,'attendance',case when student_id='30000000-0000-0000-0000-000000000001' then 'absent_unexcused' else 'present' end,'homework_status',case when student_id='30000000-0000-0000-0000-000000000001' then 'missing' else 'done' end,'old_lesson_status','passed','quick_score',case when student_id='30000000-0000-0000-0000-000000000001' then 4 else null end,'needs_attention',student_id='30000000-0000-0000-0000-000000000005','attention_reasons',case when student_id='30000000-0000-0000-0000-000000000005' then '["focus"]'::jsonb else '[]'::jsonb end,'teacher_note','private-note-marker'))) from public.session_student_records)::text,true);
select pg_temp.reject('select public.save_session_checkout('''||current_setting('p2.session')||''',1,jsonb_set('''||current_setting('p2.data')||'''::jsonb,''{records,0,quick_score}'',''11''::jsonb),true)','23514');
select pg_temp.assert_true((select count(*)=0 from public.student_events),'Invalid completion creates no events');
select pg_temp.assert_true((select count(*)=0 from public.tasks),'Invalid completion creates no tasks');
select pg_temp.assert_true((select status='in_progress' and version=1 from public.class_sessions),'Invalid completion rolls back status');
select pg_temp.reject('select public.save_session_checkout('''||current_setting('p2.session')||''',null,'''||current_setting('p2.data')||'''::jsonb,false)','40001');
select public.save_session_checkout(current_setting('p2.session')::uuid,1,current_setting('p2.data')::jsonb,false);
select pg_temp.reject('select public.save_session_checkout('''||current_setting('p2.session')||''',1,'''||current_setting('p2.data')||'''::jsonb,false)','40001');
reset role;
insert into public.session_attachments(session_id,uploaded_by,storage_path,mime_type,size_bytes) values(current_setting('p2.session')::uuid,'10000000-0000-0000-0000-000000000002',current_setting('p2.session')||'/51000000-0000-0000-0000-000000000001.png','image/png',100);
delete from public.cskh_student_assignments where student_id='30000000-0000-0000-0000-000000000005';
set local role authenticated;
set local request.jwt.claim.sub='10000000-0000-0000-0000-000000000002';
select public.save_session_checkout(current_setting('p2.session')::uuid,2,current_setting('p2.data')::jsonb,true);
reset role;
select pg_temp.assert_true((select count(*)=5 from public.tasks),'All deterministic task rules');
select pg_temp.assert_true((select count(*)=1 from public.tasks where owner_id is null),'Missing owner keeps unassigned task');
select set_config('p2.events',(select count(*)::text from public.student_events),true);
set local role authenticated;
set local request.jwt.claim.sub='10000000-0000-0000-0000-000000000002';
select public.save_session_checkout(current_setting('p2.session')::uuid,2,current_setting('p2.data')::jsonb,true);
select pg_temp.reject('select public.save_session_checkout('''||current_setting('p2.session')||''',3,'''||current_setting('p2.data')||'''::jsonb,false)');
select pg_temp.assert_true((select count(*)=1 from public.tasks),'Teacher sees only own review task');
reset role;
select pg_temp.assert_true((select count(*)=5 from public.tasks),'Replay creates no duplicate tasks');
select pg_temp.assert_true((select count(*)::text=current_setting('p2.events') from public.student_events),'Replay creates no duplicate events');
update public.profiles set active=false where id='10000000-0000-0000-0000-000000000002';
set local role authenticated;
select pg_temp.reject('select public.save_session_checkout('''||current_setting('p2.session')||''',2,'''||current_setting('p2.data')||'''::jsonb,true)','42501');
reset role;
update public.profiles set active=true where id='10000000-0000-0000-0000-000000000002';
set local role authenticated;
set local request.jwt.claim.sub='10000000-0000-0000-0000-000000000001';
select set_config('p2.second',public.create_class_session('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000002',now()-interval '50 minutes',now()-interval '10 minutes','Repeat homework')::text,true);
set local request.jwt.claim.sub='10000000-0000-0000-0000-000000000002';
select public.start_class_session(current_setting('p2.second')::uuid);
select public.save_session_checkout(current_setting('p2.second')::uuid,1,current_setting('p2.data')::jsonb,true);
select pg_temp.assert_true(public.student_pulse('30000000-0000-0000-0000-000000000001')->>'color'='red','Pulse explains repeated missing/low score');
reset role;
select pg_temp.assert_true((select count(*)=1 from public.tasks where type='homework_followup' and priority='high'),'Repeated missing raises single active task');
select pg_temp.assert_true((select count(*)=5 from public.tasks),'Cross-session deduplication');
set local role authenticated;
set local request.jwt.claim.sub='10000000-0000-0000-0000-000000000004';
select pg_temp.assert_true((select count(*)=3 from public.tasks),'CSKH gets only owned tasks');
select pg_temp.assert_true((select count(*)=0 from public.record_notes),'CSKH cannot read private notes');
select pg_temp.assert_true((select count(*)=0 from public.session_attachments),'CSKH cannot read attachments');
select pg_temp.reject('update public.session_student_records set quick_score=10','42501');
select pg_temp.assert_true(not exists(select 1 from public.student_events where summary like '%private-note-marker%'),'Timeline does not expose private notes');
select public.update_task(id,version,'done','Followed up',null,null) from public.tasks where type='homework_followup';
set local request.jwt.claim.sub='10000000-0000-0000-0000-000000000006';
select pg_temp.assert_true((select count(*)=0 from public.session_attachments),'Media cannot see private attachments');
select pg_temp.assert_true((select count(*)=0 from public.student_events),'Media cannot see timeline');
select pg_temp.reject('select public.student_pulse(''30000000-0000-0000-0000-000000000001'')','42501');
set local request.jwt.claim.sub='10000000-0000-0000-0000-000000000001';
select pg_temp.assert_true((select count(*)=1 from public.session_attachments),'Admin reads attachments');
select pg_temp.assert_true((public.command_summary()->>'unassigned')::int=1,'Admin sees missing owner exception');
-- FINAL GATE regression: immutable historical identities, including transferred/inactive.
reset role;
update public.students set class_id='20000000-0000-0000-0000-000000000002',active=false where id='30000000-0000-0000-0000-000000000001';
set local role authenticated;
set local request.jwt.claim.sub='10000000-0000-0000-0000-000000000002';
select pg_temp.assert_true((select count(*)=5 from public.session_roster(current_setting('p2.session')::uuid)),'Snapshot includes transferred/inactive identities');
select pg_temp.assert_true((select count(*)=1 from public.session_roster(current_setting('p2.session')::uuid) where id='30000000-0000-0000-0000-000000000001' and full_name is not null),'Transferred identity available without current student RLS');
select pg_temp.assert_true((select count(*)=5 from public.session_student_records where session_id=current_setting('p2.session')::uuid),'Historical record roster stable');
set local request.jwt.claim.sub='10000000-0000-0000-0000-000000000003';
select pg_temp.assert_true((select count(*)=2 from public.student_session_history('30000000-0000-0000-0000-000000000001')),'New teacher receives completed academic timestamps after transfer');
select pg_temp.assert_true((select count(*)=0 from public.session_attachments),'Academic history does not grant old class attachment access');
select pg_temp.assert_true((select count(*)=0 from public.record_notes),'New teacher cannot read originating private notes');
select pg_temp.reject('select * from public.session_roster('''||current_setting('p2.session')||''')','42501');
set local request.jwt.claim.sub='10000000-0000-0000-0000-000000000002';

select pg_temp.reject('update public.record_notes set teacher_note=''hacked''','42501');
select pg_temp.reject('update public.class_sessions set lesson_content=''hacked''','42501');
select pg_temp.reject('update public.session_attachments set mime_type=''video/mp4''','42501');
select pg_temp.reject('select public.register_session_attachment('''||current_setting('p2.session')||''','''||current_setting('p2.session')||'/51000000-0000-0000-0000-000000000001.png'',''image/png'',100)','42501');
reset role;
-- Even privileged REST/direct SQL cannot silently mutate completed history.
select pg_temp.reject('update public.session_student_records set quick_score=9 where session_id='''||current_setting('p2.session')||'''','55000');
select pg_temp.reject('update public.record_notes set teacher_note=''hacked'' where record_id in(select id from public.session_student_records where session_id='''||current_setting('p2.session')||''')','55000');
select pg_temp.reject('update public.class_sessions set lesson_content=''hacked'',homework_assigned=''hacked'' where id='''||current_setting('p2.session')||'''','55000');
select pg_temp.reject('update public.session_attachments set size_bytes=101 where session_id='''||current_setting('p2.session')||'''','55000');
select pg_temp.reject('delete from public.session_student_records where session_id='''||current_setting('p2.session')||'''','55000');
delete from public.teacher_class_assignments where teacher_id='10000000-0000-0000-0000-000000000002';
set local role authenticated;
set local request.jwt.claim.sub='10000000-0000-0000-0000-000000000002';
select pg_temp.assert_true((select count(*)=0 from public.class_sessions),'Assignment revocation removes session access');
select pg_temp.reject('select * from public.session_roster('''||current_setting('p2.session')||''')','42501');
reset role;
set local role authenticated;
set local request.jwt.claim.sub='10000000-0000-0000-0000-000000000001';
select pg_temp.assert_true((select count(*)=5 from public.session_roster(current_setting('p2.session')::uuid)),'Admin retains exact snapshot after assignment revocation');
reset role;
insert into public.teacher_class_assignments(teacher_id,class_id) values('10000000-0000-0000-0000-000000000002','20000000-0000-0000-0000-000000000001');
update public.students set class_id='20000000-0000-0000-0000-000000000001',active=true where id='30000000-0000-0000-0000-000000000001';
select set_config('p2.owner_task',(select id::text from public.tasks where type='absence_followup'),true);
select set_config('p2.owner_version',(select version::text from public.tasks where id=current_setting('p2.owner_task')::uuid),true);
update public.profiles set active=false where id='10000000-0000-0000-0000-000000000004';
set local role authenticated;
set local request.jwt.claim.sub='10000000-0000-0000-0000-000000000004';
select pg_temp.assert_true((select count(*)=0 from public.tasks),'Inactive owner cannot read');
select pg_temp.reject('select public.update_task('''||current_setting('p2.owner_task')||''','||current_setting('p2.owner_version')||',''in_progress'')','42501');
reset role;
update public.profiles set active=true where id='10000000-0000-0000-0000-000000000004';
delete from public.cskh_student_assignments where cskh_id='10000000-0000-0000-0000-000000000004' and student_id='30000000-0000-0000-0000-000000000001';
set local role authenticated;
set local request.jwt.claim.sub='10000000-0000-0000-0000-000000000004';
select pg_temp.assert_true((select count(*)=0 from public.tasks where id=current_setting('p2.owner_task')::uuid),'Unassigned old owner cannot read');
select pg_temp.reject('select public.update_task('''||current_setting('p2.owner_task')||''','||current_setting('p2.owner_version')||',''in_progress'')','42501');
set local request.jwt.claim.sub='10000000-0000-0000-0000-000000000001';
select pg_temp.assert_true((public.command_summary()->>'unassigned')::int>=2,'Admin sees revoked owner exception');
reset role;
insert into public.cskh_student_assignments(cskh_id,student_id) values('10000000-0000-0000-0000-000000000004','30000000-0000-0000-0000-000000000001'),('10000000-0000-0000-0000-000000000005','30000000-0000-0000-0000-000000000001');
set local role authenticated;
set local request.jwt.claim.sub='10000000-0000-0000-0000-000000000004';
select pg_temp.assert_true((select count(*)=0 from public.tasks where id=current_setting('p2.owner_task')::uuid),'Ambiguous owners denied task access');
set local request.jwt.claim.sub='10000000-0000-0000-0000-000000000001';
select set_config('p2.third',public.create_class_session('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000002',now()+interval '1 hour',now()+interval '2 hours','Ambiguous owner')::text,true);
set local request.jwt.claim.sub='10000000-0000-0000-0000-000000000002';
select public.start_class_session(current_setting('p2.third')::uuid);
select public.save_session_checkout(current_setting('p2.third')::uuid,1,current_setting('p2.data')::jsonb,true);
reset role;
select pg_temp.assert_true((select owner_id is null from public.tasks where id=current_setting('p2.owner_task')::uuid),'Existing task invalid owner cleared on new trigger');
select pg_temp.assert_true((select count(*)=1 from public.tasks where type='absence_followup'),'Dedup keeps one active absence task');
select pg_temp.assert_true((select metadata->>'cacheControl'='max-age=0' from storage.objects where name='legacy-cache-fixture.png'),'Legacy attachments no longer cacheable');
select pg_temp.assert_true(not exists(select 1 from information_schema.columns where table_schema='public' and table_name in ('class_sessions','tasks','student_events','session_student_records','session_attachments') and data_type='timestamp without time zone'),'All operational timestamps are timezone-aware');
select pg_temp.assert_true(('2026-10-13 16:59:59+00'::timestamptz at time zone 'Asia/Bangkok')::date='2026-10-13' and ('2026-10-13 17:00:00+00'::timestamptz at time zone 'Asia/Bangkok')::date='2026-10-14','UTC+7 midnight boundary');

-- Earlier lesson completed last must still escalate the same active task.
set local role authenticated;
set local request.jwt.claim.sub='10000000-0000-0000-0000-000000000001';
select set_config('p2.reverse_early',public.create_class_session('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000002',now()+interval '3 hours',now()+interval '4 hours','Reverse early')::text,true);
select set_config('p2.reverse_late',public.create_class_session('20000000-0000-0000-0000-000000000001','10000000-0000-0000-0000-000000000002',now()+interval '4 hours',now()+interval '5 hours','Reverse late')::text,true);
set local request.jwt.claim.sub='10000000-0000-0000-0000-000000000002';
select public.start_class_session(current_setting('p2.reverse_early')::uuid);
select public.start_class_session(current_setting('p2.reverse_late')::uuid);
select set_config('p2.reverse_data',(select jsonb_build_object('records',jsonb_agg(jsonb_build_object('student_id',student_id,'attendance','present','homework_status',case when student_id='30000000-0000-0000-0000-000000000002' then 'missing' else 'done' end,'old_lesson_status','passed','quick_score',null,'needs_attention',false,'attention_reasons','[]'::jsonb,'teacher_note',''))) from public.session_student_records where session_id=current_setting('p2.reverse_early')::uuid)::text,true);
select public.save_session_checkout(current_setting('p2.reverse_late')::uuid,1,current_setting('p2.reverse_data')::jsonb,true);
select public.save_session_checkout(current_setting('p2.reverse_early')::uuid,1,current_setting('p2.reverse_data')::jsonb,true);
reset role;
select pg_temp.assert_true((select count(*)=1 from public.tasks where student_id='30000000-0000-0000-0000-000000000002' and type='homework_followup' and priority='high'),'Reverse completion escalates one task consistently');

rollback;
select 'Teaching RPC/rules/pulse/RLS/atomicity/idempotency tests PASS' as result;
